//! Bit-exact parity with the original Java implementation.
//! `tests/data/golden.txt` was generated by running the actual
//! SimplexNoise.java + WorldBuilder.terrainHeight under a JVM
//! (see scratch driver Golden.java): `N` lines are raw f64 bit patterns
//! for noise2, `T` lines are terrain heights.

use digblock_core::simplex::noise2;
use digblock_core::worldgen::terrain_height;

const GOLDEN: &str = include_str!("data/golden.txt");

#[test]
fn simplex_bit_exact_vs_java() {
	let mut checked = 0;
	for line in GOLDEN.lines() {
		let mut f = line.split_whitespace();
		if f.next() != Some("N") {
			continue;
		}
		let x = f64::from_bits(f.next().unwrap().parse::<i64>().unwrap() as u64);
		let y = f64::from_bits(f.next().unwrap().parse::<i64>().unwrap() as u64);
		let expect = f64::from_bits(f.next().unwrap().parse::<i64>().unwrap() as u64);
		let got = noise2(x, y);
		assert_eq!(
			got.to_bits(),
			expect.to_bits(),
			"noise2({x}, {y}) = {got}, Java says {expect}"
		);
		checked += 1;
	}
	assert!(checked >= 10, "golden file missing N lines");
}

#[test]
fn terrain_heights_match_java() {
	let mut checked = 0;
	for line in GOLDEN.lines() {
		let mut f = line.split_whitespace();
		if f.next() != Some("T") {
			continue;
		}
		let seed = f64::from_bits(f.next().unwrap().parse::<i64>().unwrap() as u64);
		let x: i32 = f.next().unwrap().parse().unwrap();
		let z: i32 = f.next().unwrap().parse().unwrap();
		let expect: i32 = f.next().unwrap().parse().unwrap();
		assert_eq!(
			terrain_height(x, z, seed),
			expect,
			"terrain_height({x}, {z}, seed={seed})"
		);
		checked += 1;
	}
	assert!(checked >= 300, "golden file missing T lines");
}
